#!/usr/bin/env bash
# Build libdart.a for one location module (oned | threed_sphere) in lib/<loc>/.
# obs_def_mod / obs_kind_mod are generated by preprocess into lib/<loc>/gen,
# so the two location builds can run concurrently without touching the shared
# generated sources.  Usage: build_lib.sh <oned|threed_sphere|pp> [jobs]
# ("pp" only builds the preprocess program, if needed.)
set -eu
loc=${1:?usage: build_lib.sh <oned|threed_sphere|pp> [jobs]}
jobs=${2:-$(getconf _NPROCESSORS_ONLN 2>/dev/null || echo 4)}
here=$(cd "$(dirname "$0")" && pwd)
export DART=$(cd "$here/../.." && pwd)
source "$DART"/build_templates/buildfunctions.sh
dartversion

# build preprocess if needed (callers do this once before launching
# concurrent library builds)
pp_dir=$DART/assimilation_code/programs/preprocess
if [ ! -x "$pp_dir/preprocess" ]; then
  ( cd "$pp_dir" && "$DART"/build_templates/mkmf -c "$version_def" -x -p "$pp_dir/preprocess" \
      -a "$DART" "$pp_dir/path_names_preprocess" ) > /dev/null 2>&1
fi
[ "$loc" = pp ] && exit 0

cd "$here/$loc"
rm -rf gen; mkdir gen
rm -f -- libdart.a *.o *.mod Makefile .cppdefs *.gcda *.gcno

MODEL=none; LOCATION=$loc; mpisrc=null_mpi; m=""
case $loc in
  oned)          EXTRA=$DART/models/template/oned_model_mod.f90 ;;
  threed_sphere) EXTRA=$DART/models/template/threed_model_mod.f90 ;;
  *) echo "unknown location $loc" >&2; exit 2 ;;
esac

"$pp_dir/preprocess" > preprocess.log 2>&1

findsrc 2>/dev/null
# swap shared generated files for this library's private ones
dartsrc=${dartsrc//$DART\/observations\/forward_operators\/obs_def_mod.f90/$PWD/gen/obs_def_mod.f90}
dartsrc=${dartsrc//$DART\/assimilation_code\/modules\/observations\/obs_kind_mod.f90/$PWD/gen/obs_kind_mod.f90}

"$DART"/build_templates/mkmf -c "$version_def" -a "$DART" -p libdart.a \
    $dartsrc $EXTRA "$DART"/developer_tests/contrib/fortran-testanything/test.f90 > mkmf.log 2>&1
# DART_COVERAGE=1: instrument for gcov (OTHERFLAGS follows FFLAGS, so -O0 wins)
extra=""; [ "${DART_COVERAGE:-0}" = 1 ] && extra="-O0 -g --coverage"
make -j"$jobs" -f Makefile OTHERFLAGS="$extra" libdart.a > make.log 2>&1
rm -f -- *.o
echo "built lib/$loc/libdart.a"
